CREATE OR REPLACE FUNCTION public.edit_approved_finance_expense_atomic(p_expense_id uuid, p_payload jsonb, p_bank_statement_line_id uuid DEFAULT NULL::uuid, p_allocation_amount numeric DEFAULT NULL::numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_exp public.finance_expenses%rowtype;
  v_journal_id uuid;
  v_journal_count integer;
  v_date date;
  v_bank_id uuid;
  v_bank_currency text;
  v_currency text;
  v_rate numeric;
  v_docs text[];
  v_period_status text;
  v_effective_allocation numeric;
  v_bpjs_ded numeric;
  v_bpjs_item_id uuid;
  v_p_month integer;
  v_p_year integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  PERFORM public._sec_check_finance_role();
  SELECT * INTO v_exp FROM public.finance_expenses WHERE id=p_expense_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;
  IF v_exp.approval_status<>'approved' THEN RAISE EXCEPTION 'Approved expense edit requires an approved expense'; END IF;

  SELECT count(*),(array_agg(id ORDER BY created_at DESC,id DESC))[1]
    INTO v_journal_count,v_journal_id
    FROM public.journal_entries
   WHERE source_module IN('expense','expenses')
     AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)
     AND is_posted=true AND NOT COALESCE(is_reversed,false);
  IF v_journal_count<>1 THEN RAISE EXCEPTION 'Approved expense must have exactly one active effective journal'; END IF;
  PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;

  SELECT ap.status INTO v_period_status
    FROM public.journal_entries je
    LEFT JOIN public.accounting_periods ap
      ON ap.start_date<=je.entry_date AND ap.end_date>=je.entry_date
   WHERE je.id=v_journal_id
   ORDER BY ap.start_date DESC LIMIT 1;
  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN
    RAISE EXCEPTION 'Cannot edit approved expense in a closed accounting period';
  END IF;

  IF COALESCE((p_payload->>'amount')::numeric,0)<=0 THEN RAISE EXCEPTION 'Expense amount must be greater than zero'; END IF;
  IF NULLIF(p_payload->>'expense_category','') IS NULL THEN RAISE EXCEPTION 'Expense category is required'; END IF;
  v_date:=COALESCE((p_payload->>'expense_date')::date,current_date);
  v_bank_id:=NULLIF(p_payload->>'bank_account_id','')::uuid;

  IF v_bank_id IS NOT NULL THEN
    SELECT currency INTO v_bank_currency FROM public.bank_accounts WHERE id=v_bank_id;
    IF v_bank_currency IS NULL THEN RAISE EXCEPTION 'Selected bank account does not exist'; END IF;
  END IF;

  v_currency:=COALESCE(NULLIF(p_payload->>'transaction_currency',''),v_bank_currency,v_exp.transaction_currency,'IDR');
  IF v_currency='USD' THEN
    v_rate:=COALESCE((p_payload->>'exchange_rate')::numeric,v_exp.exchange_rate,1);
    IF v_rate<=1 THEN RAISE EXCEPTION 'A valid USD rate greater than 1 is required'; END IF;
  ELSE
    v_currency:='IDR';
    v_rate:=1;
  END IF;

  IF p_payload ? 'document_urls' THEN
    SELECT COALESCE(array_agg(elem::text),ARRAY[]::text[])
      INTO v_docs
      FROM jsonb_array_elements_text(p_payload->'document_urls') AS elem;
  ELSE
    v_docs:=v_exp.document_urls;
  END IF;

  v_bpjs_ded := COALESCE(NULLIF(p_payload->>'bpjs_employee_deduction','')::numeric, v_exp.bpjs_employee_deduction, 0);
  v_bpjs_item_id := COALESCE(NULLIF(p_payload->>'bpjs_register_item_id','')::uuid, v_exp.bpjs_register_item_id);
  v_p_month := COALESCE(NULLIF(p_payload->>'payroll_period_month','')::integer, v_exp.payroll_period_month);
  v_p_year := COALESCE(NULLIF(p_payload->>'payroll_period_year','')::integer, v_exp.payroll_period_year);

  UPDATE public.finance_expenses SET
    expense_category=p_payload->>'expense_category',
    expense_type=COALESCE(NULLIF(p_payload->>'expense_type',''),v_exp.expense_type,'general'),
    amount=(p_payload->>'amount')::numeric,
    expense_date=v_date,
    description=NULLIF(p_payload->>'description',''),
    batch_id=NULLIF(p_payload->>'batch_id','')::uuid,
    import_container_id=NULLIF(p_payload->>'import_container_id','')::uuid,
    delivery_challan_id=NULLIF(p_payload->>'delivery_challan_id','')::uuid,
    payment_method=NULLIF(p_payload->>'payment_method',''),
    bank_account_id=v_bank_id,
    payment_reference=NULLIF(p_payload->>'payment_reference',''),
    paid_by=CASE WHEN NULLIF(p_payload->>'payment_method','') IN('cash','petty_cash') THEN 'cash' WHEN v_bank_id IS NOT NULL THEN 'bank' ELSE NULL END,
    document_urls=v_docs,
    supplier_id=NULLIF(p_payload->>'supplier_id','')::uuid,
    staff_id=NULLIF(p_payload->>'staff_id','')::uuid,
    payee_id=NULLIF(p_payload->>'payee_id','')::uuid,
    invoice_number=NULLIF(p_payload->>'invoice_number',''),
    due_date=NULLIF(p_payload->>'due_date','')::date,
    broker_items=NULLIF(p_payload->'broker_items','null'::jsonb),
    pib_bm_amount=NULLIF(p_payload->>'pib_bm_amount','')::numeric,
    pib_ppn_amount=NULLIF(p_payload->>'pib_ppn_amount','')::numeric,
    pib_pph_amount=NULLIF(p_payload->>'pib_pph_amount','')::numeric,
    ppn_amount=COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0),
    ppn_manual_override=COALESCE((p_payload->>'ppn_manual_override')::boolean,false),
    ppn_calc_mode=COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'),
    dpp_amount=NULLIF(p_payload->>'dpp_amount','')::numeric,
    ppn_rate=COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11),
    pph_amount=COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),
    pph_code_id=NULLIF(p_payload->>'pph_code_id','')::uuid,
    pph_treatment=COALESCE(NULLIF(p_payload->>'pph_treatment',''),'deduct'),
    stamp_duty_amount=COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),
    fixed_asset_account_id=NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,
    bank_charges_amount=COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),
    currency_code=v_currency,
    transaction_currency=v_currency,
    functional_currency='IDR',
    exchange_rate=v_rate,
    bank_account_currency=COALESCE(v_bank_currency,v_currency),
    payment_currency=v_currency,
    sales_order_allocations=COALESCE(p_payload->'sales_order_allocations','[]'::jsonb),
    bpjs_employee_deduction=v_bpjs_ded,
    bpjs_register_item_id=v_bpjs_item_id,
    payroll_period_month=v_p_month,
    payroll_period_year=v_p_year
  WHERE id=p_expense_id;

  RETURN p_expense_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_batch_doc_to_universal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_batch RECORD;
  v_doc_id UUID;
  v_ver_id UUID;
  v_doc_type TEXT;
  v_bucket TEXT;
  v_path TEXT;
  v_status TEXT;
  v_link_count INT;
BEGIN
  IF pg_trigger_depth() > 1 THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    SELECT id, lifecycle_status INTO v_doc_id, v_status FROM universal_documents 
    WHERE legacy_source_table = 'batch_documents' AND legacy_source_id = OLD.id;

    IF v_doc_id IS NOT NULL THEN
      DELETE FROM universal_document_links 
      WHERE document_id = v_doc_id AND entity_type = 'batch' AND entity_id = OLD.batch_id;

      IF v_status = 'BANKED' THEN
        UPDATE universal_documents SET legacy_source_id = NULL WHERE id = v_doc_id;
      ELSIF v_status = 'ARCHIVED' THEN
        UPDATE universal_documents SET legacy_source_id = NULL WHERE id = v_doc_id;
      ELSIF v_status = 'TEMP' THEN
        SELECT count(*) INTO v_link_count FROM universal_document_links WHERE document_id = v_doc_id;
        IF v_link_count = 0 THEN
          DELETE FROM universal_document_versions WHERE document_id = v_doc_id;
          DELETE FROM universal_documents WHERE id = v_doc_id;
        ELSE
          UPDATE universal_documents SET legacy_source_id = NULL WHERE id = v_doc_id;
        END IF;
      END IF;
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    SELECT id INTO v_doc_id FROM universal_documents 
    WHERE legacy_source_table = 'batch_documents' AND legacy_source_id = NEW.id;

    IF v_doc_id IS NOT NULL THEN
      UPDATE universal_documents 
      SET 
        title = COALESCE(NEW.file_name, universal_documents.title),
        updated_at = now()
      WHERE id = v_doc_id;
    END IF;
    RETURN NEW;
  END IF;

  -- TG_OP = 'INSERT'
  IF EXISTS (SELECT 1 FROM universal_documents WHERE legacy_source_table = 'batch_documents' AND legacy_source_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  SELECT batch_number, product_id, make_id INTO v_batch FROM batches WHERE id = NEW.batch_id;

  IF NEW.file_type ILIKE '%coa%' THEN
    v_doc_type := 'COA';
  ELSIF NEW.file_type ILIKE '%invoice%' THEN
    v_doc_type := 'PURCHASE INVOICE';
  ELSIF NEW.file_type ILIKE '%msds%' THEN
    v_doc_type := 'MSDS';
  ELSE
    v_doc_type := 'OTHER TECHNICAL';
  END IF;

  v_bucket := 'batch-documents';
  v_path := COALESCE(NEW.file_url, '');
  IF POSITION('/public/batch-documents/' IN v_path) > 0 THEN
    v_path := SUBSTRING(v_path FROM POSITION('/public/batch-documents/' IN v_path) + 24);
  END IF;

  INSERT INTO universal_documents (
    title, document_type, lifecycle_status, source_module,
    primary_product_id, primary_product_source_id, primary_batch_id, batch_number,
    legacy_source_table, legacy_source_id, created_by, created_at, updated_at
  ) VALUES (
    COALESCE(NEW.file_name, 'Batch Document'),
    v_doc_type,
    'BANKED',
    'batches',
    v_batch.product_id,
    v_batch.make_id,
    NEW.batch_id,
    v_batch.batch_number,
    'batch_documents',
    NEW.id,
    NEW.uploaded_by,
    COALESCE(NEW.uploaded_at, now()),
    now()
  ) RETURNING id INTO v_doc_id;

  INSERT INTO universal_document_versions (
    document_id, version_number, storage_bucket, storage_path, file_url,
    original_file_name, file_size, change_summary, is_current, uploaded_by, created_at
  ) VALUES (
    v_doc_id, 1, v_bucket, v_path, NEW.file_url,
    COALESCE(NEW.file_name, 'Batch Document'),
    COALESCE(NEW.file_size, 0),
    'Synced from batch_documents',
    true,
    NEW.uploaded_by,
    COALESCE(NEW.uploaded_at, now())
  ) RETURNING id INTO v_ver_id;

  UPDATE universal_documents SET current_version_id = v_ver_id WHERE id = v_doc_id;

  INSERT INTO universal_document_links (
    document_id, document_version_id, entity_type, entity_id,
    product_id, product_source_id, batch_id, batch_number, is_primary, created_by, created_at
  ) VALUES (
    v_doc_id, v_ver_id, 'batch', NEW.batch_id,
    v_batch.product_id, v_batch.make_id, NEW.batch_id, v_batch.batch_number,
    true, NEW.uploaded_by, COALESCE(NEW.uploaded_at, now())
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_crm_doc_to_universal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_doc_id UUID;
  v_ver_id UUID;
  v_doc_type TEXT;
  v_bucket TEXT;
  v_path TEXT;
  v_status TEXT;
  v_link_count INT;
BEGIN
  IF pg_trigger_depth() > 1 THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    SELECT id, lifecycle_status INTO v_doc_id, v_status FROM universal_documents 
    WHERE legacy_source_table = 'crm_product_documents' AND legacy_source_id = OLD.id;

    IF v_doc_id IS NOT NULL THEN
      -- Unlink entity references for this specific legacy record
      IF OLD.inquiry_id IS NOT NULL THEN
        DELETE FROM universal_document_links 
        WHERE document_id = v_doc_id AND entity_type = 'crm_inquiry' AND entity_id = OLD.inquiry_id;
      END IF;
      IF OLD.pricing_option_id IS NOT NULL THEN
        DELETE FROM universal_document_links 
        WHERE document_id = v_doc_id AND entity_type = 'crm_quote' AND entity_id = OLD.pricing_option_id;
      END IF;

      -- LIFECYCLE CONTRACT:
      -- 1. BANKED: PRESERVE permanent Bank record!
      IF v_status = 'BANKED' THEN
        UPDATE universal_documents SET legacy_source_id = NULL WHERE id = v_doc_id;

      -- 2. ARCHIVED: PRESERVE history!
      ELSIF v_status = 'ARCHIVED' THEN
        UPDATE universal_documents SET legacy_source_id = NULL WHERE id = v_doc_id;

      -- 3. TEMP:
      ELSIF v_status = 'TEMP' THEN
        SELECT count(*) INTO v_link_count FROM universal_document_links WHERE document_id = v_doc_id;
        IF v_link_count = 0 THEN
          -- TEMP with no remaining references: delete Bank record
          DELETE FROM universal_document_versions WHERE document_id = v_doc_id;
          DELETE FROM universal_documents WHERE id = v_doc_id;
        ELSE
          -- TEMP with other references: remove only the current reference
          UPDATE universal_documents SET legacy_source_id = NULL WHERE id = v_doc_id;
        END IF;
      END IF;
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    SELECT id INTO v_doc_id FROM universal_documents 
    WHERE legacy_source_table = 'crm_product_documents' AND legacy_source_id = NEW.id;

    IF v_doc_id IS NOT NULL THEN
      v_status := COALESCE(NEW.lifecycle_status, CASE WHEN NEW.is_permanent THEN 'BANKED' ELSE 'TEMP' END);

      UPDATE universal_documents 
      SET 
        lifecycle_status = v_status,
        specification = COALESCE(NEW.specification, universal_documents.specification),
        primary_product_id = COALESCE(NEW.product_id, universal_documents.primary_product_id),
        primary_product_source_id = COALESCE(NEW.product_source_id, universal_documents.primary_product_source_id),
        primary_batch_id = COALESCE(NEW.batch_id, universal_documents.primary_batch_id),
        batch_number = COALESCE(NEW.batch_number, universal_documents.batch_number),
        valid_until = COALESCE(NEW.valid_until, universal_documents.valid_until),
        reviewed_by = COALESCE(NEW.reviewed_by, universal_documents.reviewed_by),
        reviewed_at = COALESCE(NEW.reviewed_at, universal_documents.reviewed_at),
        updated_at = now()
      WHERE id = v_doc_id;
    END IF;
    RETURN NEW;
  END IF;

  -- TG_OP = 'INSERT'
  IF EXISTS (SELECT 1 FROM universal_documents WHERE legacy_source_table = 'crm_product_documents' AND legacy_source_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  v_doc_type := COALESCE(NEW.document_type, 'OTHER TECHNICAL');
  IF v_doc_type = 'SPEC' THEN
    v_doc_type := 'SPECIFICATION';
  END IF;

  v_status := COALESCE(NEW.lifecycle_status, CASE WHEN NEW.is_permanent THEN 'BANKED' ELSE 'TEMP' END);

  v_bucket := COALESCE(NEW.storage_bucket, 'crm-documents');
  v_path := COALESCE(NEW.storage_path, '');

  INSERT INTO universal_documents (
    title, document_type, specification, lifecycle_status, source_module,
    primary_product_id, primary_product_source_id, primary_batch_id, batch_number,
    valid_until, reviewed_by, reviewed_at,
    legacy_source_table, legacy_source_id, created_by, created_at, updated_at
  ) VALUES (
    COALESCE(NEW.display_file_name, NEW.original_file_name, 'CRM Document'),
    v_doc_type,
    NEW.specification,
    v_status,
    'crm',
    NEW.product_id,
    NEW.product_source_id,
    NEW.batch_id,
    NEW.batch_number,
    NEW.valid_until,
    NEW.reviewed_by,
    NEW.reviewed_at,
    'crm_product_documents',
    NEW.id,
    NEW.uploaded_by,
    COALESCE(NEW.created_at, now()),
    now()
  ) RETURNING id INTO v_doc_id;

  INSERT INTO universal_document_versions (
    document_id, version_number, storage_bucket, storage_path, file_url,
    original_file_name, file_size, mime_type, sha256, change_summary, is_current, uploaded_by, created_at
  ) VALUES (
    v_doc_id, 1, v_bucket, v_path, NULL,
    COALESCE(NEW.original_file_name, 'CRM Document'),
    COALESCE(NEW.file_size, 0),
    NEW.mime_type,
    NEW.sha256,
    'Synced from crm_product_documents',
    true,
    NEW.uploaded_by,
    COALESCE(NEW.created_at, now())
  ) RETURNING id INTO v_ver_id;

  UPDATE universal_documents SET current_version_id = v_ver_id WHERE id = v_doc_id;

  IF NEW.inquiry_id IS NOT NULL THEN
    INSERT INTO universal_document_links (
      document_id, document_version_id, entity_type, entity_id,
      product_id, product_source_id, batch_id, batch_number, is_primary, created_by, created_at
    ) VALUES (
      v_doc_id, v_ver_id, 'crm_inquiry', NEW.inquiry_id,
      NEW.product_id, NEW.product_source_id, NEW.batch_id, NEW.batch_number, false, NEW.uploaded_by, COALESCE(NEW.created_at, now())
    );
  END IF;

  IF NEW.pricing_option_id IS NOT NULL THEN
    INSERT INTO universal_document_links (
      document_id, document_version_id, entity_type, entity_id,
      product_id, product_source_id, batch_id, batch_number, is_primary, created_by, created_at
    ) VALUES (
      v_doc_id, v_ver_id, 'crm_quote', NEW.pricing_option_id,
      NEW.product_id, NEW.product_source_id, NEW.batch_id, NEW.batch_number, false, NEW.uploaded_by, COALESCE(NEW.created_at, now())
    );
  END IF;

  IF NEW.product_id IS NOT NULL THEN
    INSERT INTO universal_document_links (
      document_id, document_version_id, entity_type, entity_id,
      product_id, product_source_id, batch_id, batch_number, is_primary, created_by, created_at
    ) VALUES (
      v_doc_id, v_ver_id, 'product', NEW.product_id,
      NEW.product_id, NEW.product_source_id, NEW.batch_id, NEW.batch_number, true, NEW.uploaded_by, COALESCE(NEW.created_at, now())
    );
  END IF;

  RETURN NEW;
END;
$function$

